(256427, 17092, 7607, '<td valign="top">Good job. Great idea...wish I''d thought of it</td>', 'Good job. Great idea...wish I''d thought of it', '2003-04-07 12:16:28.000000', NULL, 1),
(256432, 17387, 2302, '<td valign="top">I love the contrast of the rusting structure against the blue sky. My favorite in the challenge - Good luck! = 9</td>', 'I love the contrast of the rusting structure against the blue sky. My favorite in the challenge - Good luck! = 9', '2003-04-07 12:19:27.000000', NULL, 1),
(256435, 17503, 7607, '<td valign="top">Very well put together showing the topic.Maybe not the most interesting photo,but then the subject isn''t all that interesting either. You did very well here in a very traditional way. Good job</td>', 'Very well put together showing the topic.Maybe not the most interesting photo,but then the subject isn''t all that interesting either. You did very well here in a very traditional way. Good job', '2003-04-07 12:20:31.000000', NULL, 1),
(256436, 17147, 2302, '<td valign="top">I think the lighting could have been better here but overall it is pretty good. Perhaps a lighter colored background would have helped.  = 6</td>', 'I think the lighting could have been better here but overall it is pretty good. Perhaps a lighter colored background would have helped.  = 6', '2003-04-07 12:21:27.000000', NULL, 1),
(256440, 17287, 7607, '<td valign="top">Deffinately a "how they do that". This is awsome.Well done</td>', 'Deffinately a "how they do that". This is awsome.Well done', '2003-04-07 12:23:28.000000', NULL, 1),
(256448, 17191, 7607, '<td valign="top">Great idea! Ya did good.</td>', 'Great idea! Ya did good.', '2003-04-07 12:26:15.000000', NULL, 1),
(256454, 17310, 7607, '<td valign="top">Wonderful title and "a picture worth a thousand words"</td>', 'Wonderful title and "a picture worth a thousand words"', '2003-04-07 12:28:15.000000', NULL, 1),
(256470, 17295, 7607, '<td valign="top">Very well done. Love the toning here and I hope you  get high marks for this very original idea. Took a few minutes to find the 3rd one which really gets the viewer involved here. Great job!</td>', 'Very well done. Love the toning here and I hope you  get high marks for this very original idea. Took a few minutes to find the 3rd one which really gets the viewer involved here. Great job!', '2003-04-07 12:34:55.000000', NULL, 1),
(256475, 17308, 7607, '<td valign="top">Nice play on words. Photo is alittle dark to me but well done.</td>', 'Nice play on words. Photo is alittle dark to me but well done.', '2003-04-07 12:36:28.000000', NULL, 1),
(256479, 17171, 7607, '<td valign="top">Exactly! Well done.</td>', 'Exactly! Well done.', '2003-04-07 12:37:47.000000', NULL, 1),
