(256483, 17595, 7607, '<td valign="top">Good job. Interesting point of view.</td>', 'Good job. Interesting point of view.', '2003-04-07 12:41:46.000000', NULL, 1),
(256487, 17387, 3290, '<td valign="top">Thought we might see this again. Nice perspective and lighting</td>', 'Thought we might see this again. Nice perspective and lighting', '2003-04-07 12:42:31.000000', NULL, 1),
(256488, 17225, 7607, '<td valign="top">Yum,and makes a pretty photo</td>', 'Yum,and makes a pretty photo', '2003-04-07 12:42:43.000000', NULL, 1),
(256495, 17427, 3290, '<td valign="top">Nice and sharp. Good exposure.</td>', 'Nice and sharp. Good exposure.', '2003-04-07 12:45:17.000000', NULL, 1),
(256499, 17110, 7607, '<td valign="top">Good job here. Like the way you have incorporated many differnt ideas here</td>', 'Good job here. Like the way you have incorporated many differnt ideas here', '2003-04-07 12:46:06.000000', NULL, 1),
(256500, 17147, 7607, '<td valign="top">Good job</td>', 'Good job', '2003-04-07 12:46:33.000000', NULL, 1),
(256505, 17518, 7607, '<td valign="top">Very good. Nice composition and crop here. Well put demo of subject</td>', 'Very good. Nice composition and crop here. Well put demo of subject', '2003-04-07 12:49:22.000000', NULL, 1),
(256515, 17287, 7711, '<td valign="top">I''d love to know how you did this, its very striking!</td>', 'I''d love to know how you did this, its very striking!', '2003-04-07 12:58:29.000000', NULL, 1),
(256516, 17287, 6900, '<td valign="top">WOW.  How the?</td>', 'WOW.  How the?', '2003-04-07 12:58:31.000000', NULL, 1),
(256523, 17397, 2302, '<td valign="top">Great sky!  I wish the angle couls have captured the structures a bit more head on - since they are so dark it is a bit hard to see the formations. Overall pretty good - would have liked it a bit lighter in the bottom. = 6</td>', 'Great sky!  I wish the angle couls have captured the structures a bit more head on - since they are so dark it is a bit hard to see the formations. Overall pretty good - would have liked it a bit lighter in the bottom. = 6', '2003-04-07 13:02:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(256570, 17199, 4811, '<td valign="top">I don''t think I''ve ever seen an illustration that better explains the meaning of pi! Nicely colored and textured to boot!</td>', 'I don''t think I''ve ever seen an illustration that better explains the meaning of pi! Nicely colored and textured to boot!', '2003-04-07 13:22:11.000000', NULL, 1),
(256710, 17051, 7350, '<td valign="top">I love the idea.  This pizza doesn''t look particularly appetizing, however...7 for creativity.</td>', 'I love the idea.  This pizza doesn''t look particularly appetizing, however...7 for creativity.', '2003-04-07 14:02:14.000000', NULL, 1),
(256818, 17427, 1717, '<td valign="top">oooh...great shot!  the detail is amazing and i love the DOF.  nice job!</td>', 'oooh...great shot!  the detail is amazing and i love the DOF.  nice job!', '2003-04-07 14:22:09.000000', NULL, 1),
(256918, 17256, 2302, '<td valign="top">I''ll assume this is one of the shots that is too smart for me :)   I like the concept here. I don''t like the focus very much - could have liked to see all the the drawing inside the lens in focus. = 5</td>', 'I''ll assume this is one of the shots that is too smart for me :)   I like the concept here. I don''t like the focus very much - could have liked to see all the the drawing inside the lens in focus. = 5', '2003-04-07 15:03:50.000000', NULL, 1),
(256965, 17539, 6667, '<td valign="top">Reading left to right 3.14 would have been perfect.  Excelent picture. Very, very imaginative.</td>', 'Reading left to right 3.14 would have been perfect.  Excelent picture. Very, very imaginative.', '2003-04-07 15:20:04.000000', NULL, 1),
(256968, 17427, 6667, '<td valign="top">Beautifull instruments. Where, in this day and age, did you find a slide rule?  Nice shot.</td>', 'Beautifull instruments. Where, in this day and age, did you find a slide rule?  Nice shot.', '2003-04-07 15:22:42.000000', NULL, 1),
(256971, 17288, 6667, '<td valign="top">Creative!</td>', 'Creative!', '2003-04-07 15:25:18.000000', NULL, 1),
(256972, 17061, 6667, '<td valign="top">My favorite!</td>', 'My favorite!', '2003-04-07 15:25:50.000000', NULL, 1),
(256978, 16906, 2302, '<td valign="top">Ok - took me a while to get the fourth type of PI - not enough coffee this morning I guess. I think this was clever, but it looks really washed out to me - I am not sure if it is the lighting, or just too grainy but it detracts from the shot for me. I would have liked this to be really really sharp and have better balence on the outside circle so the same number of tokens showed in each corner. =5</td>', 'Ok - took me a while to get the fourth type of PI - not enough coffee this morning I guess. I think this was clever, but it looks really washed out to me - I am not sure if it is the lighting, or just too grainy but it detracts from the shot for me. I would have liked this to be really really sharp and have better balence on the outside circle so the same number of tokens showed in each corner. =5', '2003-04-07 15:27:35.000000', NULL, 1),
(256987, 17312, 2302, '<td valign="top">a bit too overexposed on some of the spots - this one just doesn''t hold my interest though. = 4</td>', 'a bit too overexposed on some of the spots - this one just doesn''t hold my interest though. = 4', '2003-04-07 15:30:20.000000', NULL, 1),
(256992, 17505, 2302, '<td valign="top">Nice placement and composition but would benefit by more light - very dark. Focus also seems off - the vessel is too soft for my taste. = 4</td>', 'Nice placement and composition but would benefit by more light - very dark. Focus also seems off - the vessel is too soft for my taste. = 4', '2003-04-07 15:32:08.000000', NULL, 1),
(257003, 17287, 6667, '<td valign="top">Centered on the eye would have been better.  Contacts?  Great idea and very ingenious.</td>', 'Centered on the eye would have been better.  Contacts?  Great idea and very ingenious.', '2003-04-07 15:34:38.000000', NULL, 1),
(257087, 16783, 2302, '<td valign="top">Nice composition, great focus. I really like the leading lines = 6</td>', 'Nice composition, great focus. I really like the leading lines = 6', '2003-04-07 16:15:04.000000', NULL, 1),
(257092, 17264, 6900, '<td valign="top">In some places, the shape is very obvious - not so obvious in others.  I love the design and I almost did a transparency as well - glad I didn''t.  Great background for it but your numbers are trailing away at the bottom - if they were all the way out to the sides, it would show more pi than this does.  9.</td>', 'In some places, the shape is very obvious - not so obvious in others.  I love the design and I almost did a transparency as well - glad I didn''t.  Great background for it but your numbers are trailing away at the bottom - if they were all the way out to the sides, it would show more pi than this does.  9.', '2003-04-07 16:18:25.000000', NULL, 1),
(257095, 17406, 6870, '<td valign="top">I like. You really capture the one of the essences of pi: it\''s scattered length. And you do it in a fun way. Great lighting and composition enhance your communication here. 10</td>', 'I like. You really capture the one of the essences of pi: it\''s scattered length. And you do it in a fun way. Great lighting and composition enhance your communication here. 10', '2003-04-07 16:19:35.000000', NULL, 1),
(257100, 17427, 6870, '<td valign="top">This photo, effective in B/W, really communicates the scientific "magicalness" of pi to me. Suberb composition, I''m glad I have to look, for just a moment, to find the pi symbol.</td>', 'This photo, effective in B/W, really communicates the scientific "magicalness" of pi to me. Suberb composition, I''m glad I have to look, for just a moment, to find the pi symbol.', '2003-04-07 16:21:11.000000', NULL, 1),
(257104, 17387, 6870, '<td valign="top">Looks familiar.... I still like it, and you have a good eye for finding pi. While this is a pi shape, it doesn''t communicate anything about pi to me, or it may be more accurate to say that I can''t infer anything about pi from it.</td>', 'Looks familiar.... I still like it, and you have a good eye for finding pi. While this is a pi shape, it doesn''t communicate anything about pi to me, or it may be more accurate to say that I can''t infer anything about pi from it.', '2003-04-07 16:23:02.000000', NULL, 1),
(257114, 17374, 6870, '<td valign="top">This photo indicates to me several things: First, we hold pi (as an extension of or base of technology) high as some kind of beacon or symbol. Second, it communicates to me the complexity of pi. I read this past week that the most accurate way to describe a circle, when relating to pi, is that a circle is an infinite number of corners put together. This hints at that to me.</td>', 'This photo indicates to me several things: First, we hold pi (as an extension of or base of technology) high as some kind of beacon or symbol. Second, it communicates to me the complexity of pi. I read this past week that the most accurate way to describe a circle, when relating to pi, is that a circle is an infinite number of corners put together. This hints at that to me.', '2003-04-07 16:25:52.000000', NULL, 1),
(257118, 16783, 6870, '<td valign="top">Simple and effective, you communicate both the complexity of pi, and the simple fact that it''s just a buncha numbers. Engages and intrigues me, but doesn''t do much for me emotionally (can any pi shot?). I  hope this does well. 9</td>', 'Simple and effective, you communicate both the complexity of pi, and the simple fact that it''s just a buncha numbers. Engages and intrigues me, but doesn''t do much for me emotionally (can any pi shot?). I  hope this does well. 9', '2003-04-07 16:27:25.000000', NULL, 1),
(257124, 17181, 6870, '<td valign="top">The lighting on this pi(e) is superb. I do think it should be in focus, however. At least part of it. It is a good and expected play on words, but I still would like to see some connection with pi itself be communicated more clearly.</td>', 'The lighting on this pi(e) is superb. I do think it should be in focus, however. At least part of it. It is a good and expected play on words, but I still would like to see some connection with pi itself be communicated more clearly.', '2003-04-07 16:29:16.000000', NULL, 1),
(257130, 17418, 6870, '<td valign="top">The idea of a spinning circle is a good one, and I love the lines with the double circle. I think it would engage me more if it had more interesting lighting or shadows. Possibly if we could see the spokes more, too. They are all blurry now, and if we could see a hint of some lines, that might help me like this more.</td>', 'The idea of a spinning circle is a good one, and I love the lines with the double circle. I think it would engage me more if it had more interesting lighting or shadows. Possibly if we could see the spokes more, too. They are all blurry now, and if we could see a hint of some lines, that might help me like this more.', '2003-04-07 16:31:40.000000', NULL, 1),
(257134, 17194, 6870, '<td valign="top">I''m sure you''re receiving comments to the extent that this image does not fit the challenge, and I have to say, it''s probably true. I''m pretty liberal when it comes to interpreting challenges, but I''d still like to see some kind of connection to the real pi somehow. Maybe she could be looking through a circular object, for example, or holding a hoop, or focus on her lovely eyes: something.<br/> <br/>As for the photo itself, I think you''ve captured her personality well. I love the composition, and B/W works very well for this image. Crystal clear focus where it needst to be, and i also like the tones a lot.</td>', 'I''m sure you''re receiving comments to the extent that this image does not fit the challenge, and I have to say, it''s probably true. I''m pretty liberal when it comes to interpreting challenges, but I''d still like to see some kind of connection to the real pi somehow. Maybe she could be looking through a circular object, for example, or holding a hoop, or focus on her lovely eyes: something. As for the photo itself, I think you''ve captured her personality well. I love the composition, and B/W works very well for this image. Crystal clear focus where it needst to be, and i also like the tones a lot.', '2003-04-07 16:35:16.000000', NULL, 1),
(257138, 17489, 6870, '<td valign="top">This seems out of focus, but I like the colors and lighting, making it look like it''s floating. I would like to see this image somehow express some essence of pi rather than just have a colorful image, though.</td>', 'This seems out of focus, but I like the colors and lighting, making it look like it''s floating. I would like to see this image somehow express some essence of pi rather than just have a colorful image, though.', '2003-04-07 16:37:02.000000', NULL, 1),
(257140, 17194, 342, '<td valign="top">NIce Picture but not a real PI</td>', 'NIce Picture but not a real PI', '2003-04-07 16:37:47.000000', NULL, 1),
(257142, 17061, 6870, '<td valign="top">This is a super idea with the ruler and the lemon slice. The title confuses me, though. I also feel that the lemon should be in focus and that the ruler should somehow stand out more to communicate your message here.</td>', 'This is a super idea with the ruler and the lemon slice. The title confuses me, though. I also feel that the lemon should be in focus and that the ruler should somehow stand out more to communicate your message here.', '2003-04-07 16:38:37.000000', NULL, 1),
(257143, 17229, 342, '<td valign="top">Am I missing something, I do not get it.</td>', 'Am I missing something, I do not get it.', '2003-04-07 16:38:44.000000', NULL, 1),
(257147, 17110, 342, '<td valign="top">This should have done well for kitchen art.  And what wojlld be the answer to this equation?</td>', 'This should have done well for kitchen art.  And what wojlld be the answer to this equation?', '2003-04-07 16:41:33.000000', NULL, 1),
(257162, 16842, 342, '<td valign="top">Is this CWRU?</td>', 'Is this CWRU?', '2003-04-07 16:51:35.000000', NULL, 1),
(257236, 17283, 7438, '<td valign="top">The idea is good, but the pi symbol doesn''t fit in well enough. It needs something to make it pop, like an interesting color contrast .</td>', 'The idea is good, but the pi symbol doesn''t fit in well enough. It needs something to make it pop, like an interesting color contrast .', '2003-04-07 17:37:55.000000', NULL, 1),
(257253, 17494, 7438, '<td valign="top">I like the idea, but the crop makes it a bit cluttered. And another thing: I would''ve named it ''Peye''. It''s a bit on-the-nose, but who can resist such a pun? :)</td>', 'I like the idea, but the crop makes it a bit cluttered. And another thing: I would''ve named it ''Peye''. It''s a bit on-the-nose, but who can resist such a pun? :)', '2003-04-07 17:44:47.000000', NULL, 1),
(257260, 17387, 3607, '<td valign="top">have we seen this before ;-)  i still like it, and am very jealous of your weather.  not much to say on your shot except maybe trying w/the object not so centered, maybe a bit towards the left or right lower corner and capture more sky.  i wonder if you had cropped the photo in the shape of a circle if that would have broken the rules.</td>', 'have we seen this before ;-)  i still like it, and am very jealous of your weather.  not much to say on your shot except maybe trying w/the object not so centered, maybe a bit towards the left or right lower corner and capture more sky.  i wonder if you had cropped the photo in the shape of a circle if that would have broken the rules.', '2003-04-07 17:49:23.000000', NULL, 1),
(257264, 16783, 3607, '<td valign="top">i think this is really cool and well done.  sorry, i don''t have any suggestions on how to improve on this.</td>', 'i think this is really cool and well done.  sorry, i don''t have any suggestions on how to improve on this.', '2003-04-07 17:50:13.000000', NULL, 1),
(257267, 17406, 3607, '<td valign="top">very neat.  did you have fun cutting out the ribbons?  well executed and good choice in b&amp;w.  nice use of DOF.</td>', 'very neat.  did you have fun cutting out the ribbons?  well executed and good choice in b&w.  nice use of DOF.', '2003-04-07 17:51:20.000000', NULL, 1),
(257270, 17494, 3607, '<td valign="top">my top vote getter this week.  excellent job.  this is a tough shot w/out having to worry about captureing the pi reflection. . .  good use of panoramic display as well.</td>', 'my top vote getter this week.  excellent job.  this is a tough shot w/out having to worry about captureing the pi reflection. . .  good use of panoramic display as well.', '2003-04-07 17:52:13.000000', NULL, 1),
(257274, 17092, 3607, '<td valign="top">i think the idea is great and well executed (although an edible R would have been better).  ideas for improvement - not so low of an angle, maybe picking a different surface that would distract less from the subject, better lighting.  overall i had to laugh when i saw it and marvel at your creativity.</td>', 'i think the idea is great and well executed (although an edible R would have been better).  ideas for improvement - not so low of an angle, maybe picking a different surface that would distract less from the subject, better lighting.  overall i had to laugh when i saw it and marvel at your creativity.', '2003-04-07 17:54:35.000000', NULL, 1),
(257278, 17070, 3607, '<td valign="top">well done, good lighting, nice borders, you get to eat the props after the shoot - one of my top picks this week.</td>', 'well done, good lighting, nice borders, you get to eat the props after the shoot - one of my top picks this week.', '2003-04-07 17:55:55.000000', NULL, 1),
(257284, 17118, 3607, '<td valign="top">sorry - feel this is a little too off subject (although not bad photo of these little critters, they don''t stand still for very long, especially when you want to get close).</td>', 'sorry - feel this is a little too off subject (although not bad photo of these little critters, they don''t stand still for very long, especially when you want to get close).', '2003-04-07 17:57:39.000000', NULL, 1),
(257288, 17288, 3607, '<td valign="top">bronze object, glass of water, clock . . . ?  sorry, i don''t get it.<br/> <br/>as a photo of these objects, the lighting is a little weak, and they seem to be at a slant down to the right, and you can see the edge of the background on the right as well.</td>', 'bronze object, glass of water, clock . . . ?  sorry, i don''t get it. as a photo of these objects, the lighting is a little weak, and they seem to be at a slant down to the right, and you can see the edge of the background on the right as well.', '2003-04-07 17:59:35.000000', NULL, 1),
(257292, 17290, 3607, '<td valign="top">huh?</td>', 'huh?', '2003-04-07 18:01:02.000000', NULL, 1),
(257298, 17229, 3607, '<td valign="top">focus seems to be a bit soft, think in meeting the challenge subject its just okay, and the handle isn''t centered.</td>', 'focus seems to be a bit soft, think in meeting the challenge subject its just okay, and the handle isn''t centered.', '2003-04-07 18:02:41.000000', NULL, 1),
(257299, 17397, 3087, '<td valign="top"><b>Critique from Kavey</b> <br/> <br/> <br/><b>Initial thoughts</b> <br/>Very atmospheric. Slightly too pink.<br/> <br/><b>Composition/ Content</b> <br/>I like the inclusion of a lot of sky  and that the actual subject is situated only in the lower third. Although I know how large the stones are, this reminds me of how small they are too when viewed on a different scale. It feels like they are shrinking away from the weather.<br/>I would prefer to have a view that showed me more arches and less blocks  that would make the composition more interesting as well as reflect the challenge more strongly. <br/>One idea would be to take a similar picture of just one arch  with same background and same positioning in lower third, but portrait.<br/> <br/><b>Background</b> <br/>Great feeling of oppression in the clouds. Too pink for me.<br/> <br/><b>Camera Work - Technical</b> <br/>Seems fine. Hard to tell.<br/> <br/><b>Digital Processing - Technical</b> <br/>Seems fine, too pink.<br/> <br/><b>Fits The Challenge</b> <br/>Yes, though not as obviously as it could.<br/> <br/><b>My Opinion On The Photo</b> <br/>I like it but its not a favourite.<br/></td>', 'Critique from Kavey   Initial thoughts Very atmospheric. Slightly too pink. Composition/ Content I like the inclusion of a lot of sky  and that the actual subject is situated only in the lower third. Although I know how large the stones are, this reminds me of how small they are too when viewed on a different scale. It feels like they are shrinking away from the weather.I would prefer to have a view that showed me more arches and less blocks  that would make the composition more interesting as well as reflect the challenge more strongly. One idea would be to take a similar picture of just one arch  with same background and same positioning in lower third, but portrait. Background Great feeling of oppression in the clouds. Too pink for me. Camera Work - Technical Seems fine. Hard to tell. Digital Processing - Technical Seems fine, too pink. Fits The Challenge Yes, though not as obviously as it could. My Opinion On The Photo I like it but its not a favourite.', '2003-04-07 18:02:50.000000', NULL, 1),
(257302, 16780, 3607, '<td valign="top">sorry - ain''t seeing it.  also is the focus a little soft or the photo overexposed.  the center doesn''t seem as crisp as it could be for this type of shot (but you do have some symmetry ;-)</td>', 'sorry - ain''t seeing it.  also is the focus a little soft or the photo overexposed.  the center doesn''t seem as crisp as it could be for this type of shot (but you do have some symmetry ;-)', '2003-04-07 18:04:41.000000', NULL, 1),
(257304, 17374, 3607, '<td valign="top">well . . . something''s being held in the sky, but i''m not seeing pi.  i don''t know how delicate this object is, but if you could have tossed it up/taken photo ie: removed hand from the picture it would have been much better.</td>', 'well . . . something''s being held in the sky, but i''m not seeing pi.  i don''t know how delicate this object is, but if you could have tossed it up/taken photo ie: removed hand from the picture it would have been much better.', '2003-04-07 18:06:05.000000', NULL, 1),
(257307, 17287, 7350, '<td valign="top">Did you paint that on a contact lens or something?  I hope you''re going to tell us how you did it.  This is my pick of the week.  I''ll even admit it is better than my own submission.  I''m giving it a 10.</td>', 'Did you paint that on a contact lens or something?  I hope you''re going to tell us how you did it.  This is my pick of the week.  I''ll even admit it is better than my own submission.  I''m giving it a 10.', '2003-04-07 18:06:38.000000', NULL, 1),
(257310, 17397, 7350, '<td valign="top">I was hoping we''d get one of these--I''d have done it myself if I weren''t thousands of miles away.  The skyline adds to the "mystery" of the place.  9 from me.</td>', 'I was hoping we''d get one of these--I''d have done it myself if I weren''t thousands of miles away.  The skyline adds to the "mystery" of the place.  9 from me.', '2003-04-07 18:07:47.000000', NULL, 1),
(257313, 17387, 7350, '<td valign="top">I liked it last week, and I like it this week.  9</td>', 'I liked it last week, and I like it this week.  9', '2003-04-07 18:08:38.000000', NULL, 1),
(257316, 17548, 3607, '<td valign="top">it would have been very cool if i had seen pi reflected off of the cds, or they were in the shape of pi, but as it is i''m not seeing a great fit for the challenge.  from the quality of the photo perspective, i think by adjusting the light you could have made the background ''invisible'' which might have made the picture more powerful.</td>', 'it would have been very cool if i had seen pi reflected off of the cds, or they were in the shape of pi, but as it is i''m not seeing a great fit for the challenge.  from the quality of the photo perspective, i think by adjusting the light you could have made the background ''invisible'' which might have made the picture more powerful.', '2003-04-07 18:08:57.000000', NULL, 1),
(257321, 17070, 7438, '<td valign="top">Excellent! Creative and well executed. The border looks a bit cheap though, and a black border filling the edges would''ve made it a bit more grand, and complemented the black/yellow contrast in the banana.<br/> <br/>Good title too.</td>', 'Excellent! Creative and well executed. The border looks a bit cheap though, and a black border filling the edges would''ve made it a bit more grand, and complemented the black/yellow contrast in the banana. Good title too.', '2003-04-07 18:10:07.000000', NULL, 1),
(257322, 17595, 3607, '<td valign="top">as pi i think its okay - but i can see it (as opposed to some other submissions).  as a photo, however, its not very original or compelling in terms of lighting, composition, color, etc.  i might have even rotated the photo a bit so that the floor/stairs were off but pi was more like pi, and boosted the saturation to bring the red out of the bricks a bit more.</td>', 'as pi i think its okay - but i can see it (as opposed to some other submissions).  as a photo, however, its not very original or compelling in terms of lighting, composition, color, etc.  i might have even rotated the photo a bit so that the floor/stairs were off but pi was more like pi, and boosted the saturation to bring the red out of the bricks a bit more.', '2003-04-07 18:10:41.000000', NULL, 1),
(257330, 17551, 7350, '<td valign="top">A little dark, but great idea!  Pi should equal 3.14 points, if you ask me.</td>', 'A little dark, but great idea!  Pi should equal 3.14 points, if you ask me.', '2003-04-07 18:14:25.000000', NULL, 1),
(257336, 17317, 7438, '<td valign="top">Very effective DOF, and good framing. It''s not the tidiest Pi symbol I''ve ever seen, but the fact that it''s natural makes up for it. And I''ll say it again: Good framing.</td>', 'Very effective DOF, and good framing. It''s not the tidiest Pi symbol I''ve ever seen, but the fact that it''s natural makes up for it. And I''ll say it again: Good framing.', '2003-04-07 18:17:04.000000', NULL, 1),
(257339, 16780, 6870, '<td valign="top">Striking lines, made moreso because of the contrast in this image. Pi is certainly to be found <br/>in circles, though I''d like an even clearer connection. The image is also slightly out of focus.</td>', 'Striking lines, made moreso because of the contrast in this image. Pi is certainly to be found in circles, though I''d like an even clearer connection. The image is also slightly out of focus.', '2003-04-07 18:18:22.000000', NULL, 1),
(257341, 17378, 7438, '<td valign="top">It''s a bit overexposed, but the framing is good though. The title is missing a ''w'' btw.</td>', 'It''s a bit overexposed, but the framing is good though. The title is missing a ''w'' btw.', '2003-04-07 18:19:50.000000', NULL, 1),
(257344, 17118, 6870, '<td valign="top">Aha! I finally got it: the squirrel is eating a cookie that was once round? It took me a while. You captured the squirrel well, though I''d like to see a bit more connection with the essence of pi.</td>', 'Aha! I finally got it: the squirrel is eating a cookie that was once round? It took me a while. You captured the squirrel well, though I''d like to see a bit more connection with the essence of pi.', '2003-04-07 18:20:24.000000', NULL, 1),
(257350, 17378, 6870, '<td valign="top">Okay, there''s pi, the first few numbers anyway. I''m not sure that the ocean "swallowing" the numbers says anything to me, but I like the composition of the numbers within the frame.</td>', 'Okay, there''s pi, the first few numbers anyway. I''m not sure that the ocean "swallowing" the numbers says anything to me, but I like the composition of the numbers within the frame.', '2003-04-07 18:22:18.000000', NULL, 1),
(257351, 17419, 7438, '<td valign="top">It''s a bit washed out, and it''s not very exciting either. A solid white or black background and a roomier crop would probably up it a bit, along with a sharper focus ofcourse.</td>', 'It''s a bit washed out, and it''s not very exciting either. A solid white or black background and a roomier crop would probably up it a bit, along with a sharper focus ofcourse.', '2003-04-07 18:22:59.000000', NULL, 1),
(257352, 17070, 7291, '<td valign="top">I just had to laugh.  Very clever!!!</td>', 'I just had to laugh.  Very clever!!!', '2003-04-07 18:23:57.000000', NULL, 1),
(257354, 17288, 6870, '<td valign="top">This is a collection of round objects: and so is an image about pi? That''s what I''m getting here. The photo itself shows interesting lighting, though the glare from the brass pot is a bit much.</td>', 'This is a collection of round objects: and so is an image about pi? That''s what I''m getting here. The photo itself shows interesting lighting, though the glare from the brass pot is a bit much.', '2003-04-07 18:24:09.000000', NULL, 1),
(257355, 17569, 3087, '<td valign="top"><b>Kavey Critique</b> <br/> <br/> <br/><b>Initial thoughts</b> <br/>Cute idea  nice red berries.<br/> <br/><b>Composition/ Content</b> <br/>I really like the square crop and the inclusion of the circular plate behind. Its a nice abstract shape to have a square and circle intersecting within the larger square of the image.<br/>The light is just a tad harsh  its blowing out the edges of the tinfoil and some of the lighter areas of crust.<br/>Also  did you use any kind of polarizing filter? I am wondering whether that would cut down on glare from the pie gelatin surface.<br/> <br/><b>Background</b> <br/>Nice clean white.<br/> <br/><b>Fits The Challenge</b> <br/>I think so  its a humourous take but one that does also include that circle.<br/> <br/><b>My Opinion On The Photo</b> <br/>Fun and nicely composed though not an image Id necessarily look twice at outside of this challenge.<br/></td>', 'Kavey Critique   Initial thoughts Cute idea  nice red berries. Composition/ Content I really like the square crop and the inclusion of the circular plate behind. Its a nice abstract shape to have a square and circle intersecting within the larger square of the image.The light is just a tad harsh  its blowing out the edges of the tinfoil and some of the lighter areas of crust.Also  did you use any kind of polarizing filter? I am wondering whether that would cut down on glare from the pie gelatin surface. Background Nice clean white. Fits The Challenge I think so  its a humourous take but one that does also include that circle. My Opinion On The Photo Fun and nicely composed though not an image Id necessarily look twice at outside of this challenge.', '2003-04-07 18:24:16.000000', NULL, 1),
(257358, 17572, 6870, '<td valign="top">I''m having a hard time telling what this is, but I love the colors and the mood of the photograph.</td>', 'I''m having a hard time telling what this is, but I love the colors and the mood of the photograph.', '2003-04-07 18:25:29.000000', NULL, 1),
(257365, 17110, 6870, '<td valign="top">Well composed. Your title indicates sufficiently how the pie relates to pi. I like the lighting, too. It seems that the pie is slightly out of focus.</td>', 'Well composed. Your title indicates sufficiently how the pie relates to pi. I like the lighting, too. It seems that the pie is slightly out of focus.', '2003-04-07 18:27:28.000000', NULL, 1),
(257376, 17413, 7438, '<td valign="top">The trees are a bit distracting, and the head-on view doesn''t make much of the structure - I think I see some wild-view opportunities here..</td>', 'The trees are a bit distracting, and the head-on view doesn''t make much of the structure - I think I see some wild-view opportunities here..', '2003-04-07 18:33:22.000000', NULL, 1),
(257377, 17287, 7033, '<td valign="top">Fantastic shot!  Too bad I can''t vote on this one (not a member)... I have to say your effect is absolutely incredible!!!  Aside from the effect, I love the detail of this macro shot.  On the downside, the overexposed portion around the top and right edges does take away from the overall impact of the shot.  Hope this one does well for you!</td>', 'Fantastic shot!  Too bad I can''t vote on this one (not a member)... I have to say your effect is absolutely incredible!!!  Aside from the effect, I love the detail of this macro shot.  On the downside, the overexposed portion around the top and right edges does take away from the overall impact of the shot.  Hope this one does well for you!', '2003-04-07 18:33:28.000000', NULL, 1),
(257384, 17491, 7438, '<td valign="top">I like the framing - how the sunglasses balance with the compass</td>', 'I like the framing - how the sunglasses balance with the compass', '2003-04-07 18:38:10.000000', NULL, 1),
(257392, 17388, 7438, '<td valign="top">I see where you''re going with this (the swirl on the card + the circles), but it looks a bit dull and faded. I''m not sure exactly what I would''ve done to make it work, but more contrast and less brightness would be a start.</td>', 'I see where you''re going with this (the swirl on the card + the circles), but it looks a bit dull and faded. I''m not sure exactly what I would''ve done to make it work, but more contrast and less brightness would be a start.', '2003-04-07 18:42:35.000000', NULL, 1),
