(257432, 17504, 6870, '<td valign="top">Clever and interesting. I like the colors, but I wish the pi symbols were in better focus. I''m not sure of the function of the shadowy area to the right.</td>', 'Clever and interesting. I like the colors, but I wish the pi symbols were in better focus. I''m not sure of the function of the shadowy area to the right.', '2003-04-07 19:05:20.000000', NULL, 1),
(257435, 17310, 6870, '<td valign="top">The line of Greek symbols makes a wonderfully bold and significant function of leading the eye right to the pie, which I wish was in focus.</td>', 'The line of Greek symbols makes a wonderfully bold and significant function of leading the eye right to the pie, which I wish was in focus.', '2003-04-07 19:06:55.000000', NULL, 1),
