(257447, 17317, 327, '<td valign="top">Amazing find..lol</td>', 'Amazing find..lol', '2003-04-07 19:13:17.000000', NULL, 1),
(257451, 17191, 6870, '<td valign="top">I like how the dice here remind us that pi, as a number, has chance-like qualities. The composition of the dice I also like. It looks random, but I suspect you spent several minutes arranging them just so. The focus is on the last dice, when I think the image would be stronger with them all in focus. More "mysterious" lighting would also help transport the whole image into the realm of myth and fate and chance. Pi is usually associated with circles, so I find this image refreshing.</td>', 'I like how the dice here remind us that pi, as a number, has chance-like qualities. The composition of the dice I also like. It looks random, but I suspect you spent several minutes arranging them just so. The focus is on the last dice, when I think the image would be stronger with them all in focus. More "mysterious" lighting would also help transport the whole image into the realm of myth and fate and chance. Pi is usually associated with circles, so I find this image refreshing.', '2003-04-07 19:14:37.000000', NULL, 1),
(257452, 17147, 327, '<td valign="top">This was such a hard challenge..coming up with something. YOU did well, good job, creative mind.</td>', 'This was such a hard challenge..coming up with something. YOU did well, good job, creative mind.', '2003-04-07 19:15:16.000000', NULL, 1),
(257453, 17399, 327, '<td valign="top">Very good, creative brain in you head!! Really good work.</td>', 'Very good, creative brain in you head!! Really good work.', '2003-04-07 19:16:08.000000', NULL, 1),
(257454, 17264, 327, '<td valign="top">LOL neat  answer to this weird challenge. You did well here, and it''s pretty.</td>', 'LOL neat  answer to this weird challenge. You did well here, and it''s pretty.', '2003-04-07 19:17:02.000000', NULL, 1),
(257456, 17070, 6870, '<td valign="top">Goofy and fun. Bananas are the ultimate goofy fruit. They are rarely associated with elegance. Your image does not tell me much more than that, though. Perhaps some different lighting, or a different background would help you comment on pi and not merely make a symbol out of a banana?</td>', 'Goofy and fun. Bananas are the ultimate goofy fruit. They are rarely associated with elegance. Your image does not tell me much more than that, though. Perhaps some different lighting, or a different background would help you comment on pi and not merely make a symbol out of a banana?', '2003-04-07 19:17:07.000000', NULL, 1),
(257458, 17592, 327, '<td valign="top">Too funny ....lolrotflol...what a hoot this is. Good shot too!!</td>', 'Too funny ....lolrotflol...what a hoot this is. Good shot too!!', '2003-04-07 19:17:36.000000', NULL, 1),
(257459, 17070, 327, '<td valign="top">Your just too smart for me....!! This is brilliant. Great job! WAY to GO!!!!</td>', 'Your just too smart for me....!! This is brilliant. Great job! WAY to GO!!!!', '2003-04-07 19:18:04.000000', NULL, 1),
