(257655, 17225, 6328, '<td valign="top">Sure looks tasty for a Pi.  nice colours, good lighting, good focus.</td>', 'Sure looks tasty for a Pi.  nice colours, good lighting, good focus.', '2003-04-07 20:46:14.000000', NULL, 1),
(257656, 17475, 6328, '<td valign="top">Good focus here.  Good colours, nice and sharp, good idea for the challenge.</td>', 'Good focus here.  Good colours, nice and sharp, good idea for the challenge.', '2003-04-07 20:47:05.000000', NULL, 1),
