(257944, 17070, 5266, '<td valign="top">Hilarious!!  It looks like a weird new breed of banana-animal.  You made me chuckle - thanks!!</td>', 'Hilarious!!  It looks like a weird new breed of banana-animal.  You made me chuckle - thanks!!', '2003-04-07 23:19:17.000000', NULL, 1),
(257948, 17181, 5266, '<td valign="top">Soft in focus - can barely make out the Pi symbol on the pie - I like the fact that the element is red in the oven.</td>', 'Soft in focus - can barely make out the Pi symbol on the pie - I like the fact that the element is red in the oven.', '2003-04-07 23:20:24.000000', NULL, 1),
(257951, 17264, 5266, '<td valign="top">Neat pic!!  Love the sunset part and the pi symbol stands out great against it.</td>', 'Neat pic!!  Love the sunset part and the pi symbol stands out great against it.', '2003-04-07 23:21:40.000000', NULL, 1),
(257956, 17397, 5266, '<td valign="top">Awesome!!  Would love to visit someday.  Great lighting - perfect subject for Pi</td>', 'Awesome!!  Would love to visit someday.  Great lighting - perfect subject for Pi', '2003-04-07 23:24:05.000000', NULL, 1),
(257958, 17382, 5266, '<td valign="top">Neat colors - nice shadow.  I like the overall look of this pi-neapple!!</td>', 'Neat colors - nice shadow.  I like the overall look of this pi-neapple!!', '2003-04-07 23:24:42.000000', NULL, 1),
(257961, 17378, 5266, '<td valign="top">contrast seems a bit much here. I like the idea - nice water/wave shot.</td>', 'contrast seems a bit much here. I like the idea - nice water/wave shot.', '2003-04-07 23:26:10.000000', NULL, 1),
(257972, 16783, 5007, '<td valign="top">Well done! Simple and very much in the spirit of the challenge.</td>', 'Well done! Simple and very much in the spirit of the challenge.', '2003-04-07 23:30:07.000000', NULL, 1),
(257978, 17595, 5007, '<td valign="top">Good eye! Nicely done.</td>', 'Good eye! Nicely done.', '2003-04-07 23:32:51.000000', NULL, 1),
