(257986, 17343, 5007, '<td valign="top">Too bad about the wires... if you could spot edit I''m sure you would have gotten rid of them.</td>', 'Too bad about the wires... if you could spot edit I''m sure you would have gotten rid of them.', '2003-04-07 23:35:18.000000', NULL, 1),
(257987, 16842, 5007, '<td valign="top">Interesting-- good eye.</td>', 'Interesting-- good eye.', '2003-04-07 23:35:52.000000', NULL, 1),
(257993, 17382, 5007, '<td valign="top">Very clever.</td>', 'Very clever.', '2003-04-07 23:37:46.000000', NULL, 1),
(257995, 17317, 5007, '<td valign="top">Cool shot and idea.</td>', 'Cool shot and idea.', '2003-04-07 23:38:47.000000', NULL, 1),
(257997, 17483, 5007, '<td valign="top">Nice use of this technique.</td>', 'Nice use of this technique.', '2003-04-07 23:39:47.000000', NULL, 1),
(258009, 17494, 6870, '<td valign="top">Just a bit too cropped for me, but I actually like the long horizontal: it adds a sense of "scientific constraint" for me. And of course, I''m sure you''re pleased with the reflection on the cornea. This image creates, well it''s hard to describe but it creates a kind of technological myth for me, with pi at the "magic" center. Well done!</td>', 'Just a bit too cropped for me, but I actually like the long horizontal: it adds a sense of "scientific constraint" for me. And of course, I''m sure you''re pleased with the reflection on the cornea. This image creates, well it''s hard to describe but it creates a kind of technological myth for me, with pi at the "magic" center. Well done!', '2003-04-07 23:44:39.000000', NULL, 1),
(258010, 17287, 6870, '<td valign="top">The colors of the eye shadow really add a "technological feel" to this shot. Very effective cropping and idea.</td>', 'The colors of the eye shadow really add a "technological feel" to this shot. Very effective cropping and idea.', '2003-04-07 23:45:53.000000', NULL, 1),
(258012, 17490, 6870, '<td valign="top">This is just a bizarre image, that I love a lot. It is esoteric in a scientific way, and the circles and lines reflect the challenge theme of pi well. Well done!</td>', 'This is just a bizarre image, that I love a lot. It is esoteric in a scientific way, and the circles and lines reflect the challenge theme of pi well. Well done!', '2003-04-07 23:47:15.000000', NULL, 1),
(258057, 17497, 6870, '<td valign="top">This captures the theme very well, and I love the high contrast, which adds a slightly journalistic quality to the image as if we were watching geometry happen before our very eyes.</td>', 'This captures the theme very well, and I love the high contrast, which adds a slightly journalistic quality to the image as if we were watching geometry happen before our very eyes.', '2003-04-08 00:19:05.000000', NULL, 1),
(258060, 17308, 6870, '<td valign="top">The contrast between the roundness of the ball and the squares does indeed suggest pi to me, though the title seems to not match the image. I love the tones and lighting of this shot, too. Nice work.</td>', 'The contrast between the roundness of the ball and the squares does indeed suggest pi to me, though the title seems to not match the image. I love the tones and lighting of this shot, too. Nice work.', '2003-04-08 00:20:26.000000', NULL, 1),
(258065, 17396, 6870, '<td valign="top">The tape measure is a jarring yellow to me takes away from your cool, scientific mood by reminding me of carpentry, but I love the other tools, implements and calculations. Still, this image works and I give it high marks. 8</td>', 'The tape measure is a jarring yellow to me takes away from your cool, scientific mood by reminding me of carpentry, but I love the other tools, implements and calculations. Still, this image works and I give it high marks. 8', '2003-04-08 00:23:02.000000', NULL, 1),
(258069, 17264, 6870, '<td valign="top">Very nice imagery going on here. I''ve got to tell you: the first thing I looked for was the 3.14... at the upper left. I felt just a tiny bit disappointed that the three was almost not there. This image reminds me of Math, Life, the Universe and Everything, so it goes on my high scores list. Thanks!</td>', 'Very nice imagery going on here. I''ve got to tell you: the first thing I looked for was the 3.14... at the upper left. I felt just a tiny bit disappointed that the three was almost not there. This image reminds me of Math, Life, the Universe and Everything, so it goes on my high scores list. Thanks!', '2003-04-08 00:25:14.000000', NULL, 1),
(258072, 17200, 6870, '<td valign="top">Perhaps an apt title, because this really does invoke mythic feelings about pi to me. The circles and the lines intersecting them are very effective, soothing, and almost worshipful. Nice aim!</td>', 'Perhaps an apt title, because this really does invoke mythic feelings about pi to me. The circles and the lines intersecting them are very effective, soothing, and almost worshipful. Nice aim!', '2003-04-08 00:26:44.000000', NULL, 1),
(258096, 17287, 6413, '<td valign="top">that is very cool. very good foucs.  how did you do it?</td>', 'that is very cool. very good foucs.  how did you do it?', '2003-04-08 00:50:02.000000', NULL, 1),
(258099, 17264, 6413, '<td valign="top">I like this a lot. it would be a little better if you had gotten whatever you used for the pi aligned better - the 3 is chopped off and there is some space at the bottom that isn''t covered. otherwise excellent</td>', 'I like this a lot. it would be a little better if you had gotten whatever you used for the pi aligned better - the 3 is chopped off and there is some space at the bottom that isn''t covered. otherwise excellent', '2003-04-08 00:52:12.000000', NULL, 1),
(258102, 17387, 6413, '<td valign="top">This one is by far the best! good luck and I hope it wins</td>', 'This one is by far the best! good luck and I hope it wins', '2003-04-08 00:53:53.000000', NULL, 1),
(258113, 17503, 6325, '<td valign="top">I think an overhead shot would have been stronger.</td>', 'I think an overhead shot would have been stronger.', '2003-04-08 01:04:34.000000', NULL, 1);
