(258238, 17427, 92, '<td valign="top">A perfect 10 ! The composition, detail and lighting are all right on the money !</td>', 'A perfect 10 ! The composition, detail and lighting are all right on the money !', '2003-04-08 03:04:48.000000', NULL, 1),
(258254, 17290, 6892, '<td valign="top">Beautifully arranged.</td>', 'Beautifully arranged.', '2003-04-08 03:21:46.000000', NULL, 1),
