(258265, 17396, 6892, '<td valign="top">Old mathematicians never die, they just calculate away.</td>', 'Old mathematicians never die, they just calculate away.', '2003-04-08 03:28:58.000000', NULL, 1),
(258268, 17406, 6892, '<td valign="top">Frightening, isn''t it?</td>', 'Frightening, isn''t it?', '2003-04-08 03:30:31.000000', NULL, 1),
