(259844, 17287, 1135, '<td valign="top">This one and the other eye photo are my favorites this week. I hope you share how you did this with us when the challenge is over. To bad the upper right is overexposed but the white of the eye is perfect. Nice Job!</td>', 'This one and the other eye photo are my favorites this week. I hope you share how you did this with us when the challenge is over. To bad the upper right is overexposed but the white of the eye is perfect. Nice Job!', '2003-04-09 00:02:51.000000', NULL, 1),
(259848, 17494, 1135, '<td valign="top">I like how the number draws your eye right into the center of the eye. I also like the DOF. One of my top two photos this week. Great Job!</td>', 'I like how the number draws your eye right into the center of the eye. I also like the DOF. One of my top two photos this week. Great Job!', '2003-04-09 00:05:11.000000', NULL, 1),
(259858, 17518, 1135, '<td valign="top">Very cool, I had to look at this for a while to understand what I was seeing. Nice optical illusion. I wonder if it would be even more interesting if the light were from the lower right? Nice Job!</td>', 'Very cool, I had to look at this for a while to understand what I was seeing. Nice optical illusion. I wonder if it would be even more interesting if the light were from the lower right? Nice Job!', '2003-04-09 00:08:08.000000', NULL, 1),
(259860, 17194, 1135, '<td valign="top">Very nice tonal range, from pure black to bright white. Also a very cute model. Nice Job!</td>', 'Very nice tonal range, from pure black to bright white. Also a very cute model. Nice Job!', '2003-04-09 00:10:16.000000', NULL, 1),
(259864, 17118, 1135, '<td valign="top">Nice photo but too much of a stretch to meet the challenge for me.</td>', 'Nice photo but too much of a stretch to meet the challenge for me.', '2003-04-09 00:12:18.000000', NULL, 1),
