(260018, 17308, 3669, '<td valign="top">Nicely done.  Good take on the challenge and makes for a nice abstract photo.</td>', 'Nicely done.  Good take on the challenge and makes for a nice abstract photo.', '2003-04-09 02:11:52.000000', NULL, 1),
