(264072, 17551, 1037, '<td valign="top">Nice idea. Is there a coffee stain underneath the letters though? The photo overall has a dirty feeling.</td>', 'Nice idea. Is there a coffee stain underneath the letters though? The photo overall has a dirty feeling.', '2003-04-13 13:37:27.000000', NULL, 1),
(264073, 17399, 1037, '<td valign="top">This is quite cool. Perhaps there is a bit too much going on in it though. The layered elements dilute one another, so the overall impact isn''t strong.</td>', 'This is quite cool. Perhaps there is a bit too much going on in it though. The layered elements dilute one another, so the overall impact isn''t strong.', '2003-04-13 13:40:58.000000', NULL, 1),
(264075, 17494, 4090, '<td valign="top">the winner... well done</td>', 'the winner... well done', '2003-04-13 13:45:08.000000', NULL, 1),
